package com.cpf.starter.tcp;import java.nio.file.Path;import java.time.Clock;import java.util.function.Function;import org.springframework.boot.actuate.health.*;import org.springframework.boot.autoconfigure.AutoConfiguration;import org.springframework.boot.autoconfigure.condition.*;import org.springframework.boot.context.properties.EnableConfigurationProperties;import org.springframework.context.annotation.Bean;
@AutoConfiguration @EnableConfigurationProperties(CpfTcpProperties.class) @ConditionalOnProperty(prefix="cpf.integration.tcp",name="enabled",havingValue="true") public class CpfTcpAutoConfiguration {
 @Bean CpfTcpUnknownResultStore cpfTcpUnknownResultStore(){return new CpfTcpUnknownResultStore(10000);}@Bean CpfTcpCorrelationRegistry cpfTcpCorrelationRegistry(CpfTcpProperties p){return new CpfTcpCorrelationRegistry(p.getMaxPending(),p.getMaxOrphans());}@Bean CpfTcpReconnectPolicy cpfTcpReconnectPolicy(CpfTcpProperties p){return new CpfTcpReconnectPolicy(p.getReconnectInitial(),p.getReconnectMax(),p.getReconnectJitter());}
 @Bean @ConditionalOnProperty(prefix="cpf.integration.tcp",name="tls",havingValue="true") CpfTcpTlsContextProvider cpfTcpTlsContextProvider(CpfTcpProperties p){p.validate();return new KeyStoreCpfTcpTlsContextProvider(Path.of(p.getKeyStore()),p.getKeyStorePassword().toCharArray(),Path.of(p.getTrustStore()),p.getTrustStorePassword().toCharArray());}
 @Bean @ConditionalOnProperty(prefix="cpf.integration.tcp",name="mode",havingValue="CLIENT",matchIfMissing=true) CpfTcpClient cpfTcpClient(CpfTcpProperties p,CpfTcpUnknownResultStore s,org.springframework.beans.factory.ObjectProvider<CpfTcpTlsContextProvider> tls){p.validate();return new CpfTcpClient(p,s,tls.getIfAvailable());}
 @Bean(initMethod="start",destroyMethod="close") @ConditionalOnProperty(prefix="cpf.integration.tcp",name="mode",havingValue="SERVER") CpfTcpServer cpfTcpServer(CpfTcpProperties p,org.springframework.beans.factory.ObjectProvider<Function<byte[],byte[]>> h,org.springframework.beans.factory.ObjectProvider<CpfTcpTlsContextProvider> tls){p.validate();Function<byte[],byte[]> handler=h.getIfAvailable();if(handler==null)throw new IllegalStateException("TCP SERVER mode requires Function<byte[],byte[]> handler");return new CpfTcpServer(p,handler,tls.getIfAvailable());}
 @Bean CpfTcpOperations cpfTcpOperations(CpfTcpUnknownResultStore u,CpfTcpCorrelationRegistry c){return new CpfTcpOperations(u,c);}@Bean("cpfTcpHealthIndicator") HealthIndicator health(CpfTcpProperties p,CpfTcpOperations o){return ()->Health.up().withDetail("mode",p.getMode()).withDetail("frame",p.getFrame()).withDetail("tls",p.isTls()).withDetail("operations",o.snapshot()).build();}}
